class Solution:
    def encode(self, s: str) -> str:
        def better(a, b):
            return a if len(a) <= len(b) else b
        def period(x):
            i = (x + x).find(x, 1)
            return i if i < len(x) else 0
        def dfs(x):
            ans = x
            p = period(x)
            if p:
                ans = better(ans, str(len(x) // p) + "[" + dfs(x[:p]) + "]")
            for cut in range(1, len(x)):
                ans = better(ans, dfs(x[:cut]) + dfs(x[cut:]))
            return ans
        return dfs(s)

